"""The DQN learner (PL-02 step 6); satisfies `methods.Learner`.

Spine version: online one-step Q-learning on a one-hidden-layer MLP with epsilon-greedy
exploration. Each `observe` takes one gradient step on the squared one-step TD error of that
transition's active rows; there is no replay buffer and no target network yet.
"""

import copy
import math
from collections.abc import Mapping

import numpy as np
import torch
from torch import nn

from rllab.core.types import Array, Discrete, Policy, Settings, WorldSpec
from rllab.methods.types import MethodConfig, NonFiniteError, Transition

DEFAULTS: Mapping[str, int | float] = {
    "lr": 0.001,
    "gamma": 0.99,
    "hidden": 64,
    "epsilon_start": 1.0,
    "epsilon_end": 0.05,
    "epsilon_decay_steps": 20000,
}


def full_settings(settings: Settings) -> dict[str, int | float | str | bool]:
    """`settings` over the DQN defaults; `ValueError` naming any key DQN doesn't declare."""
    unknown = sorted(set(settings) - set(DEFAULTS))
    if unknown:
        raise ValueError(f"dqn has no settings {unknown}; it declares {sorted(DEFAULTS)}")
    return {**DEFAULTS, **settings}


def q_network(obs_len: int, hidden: int, actions: int) -> nn.Sequential:
    """The Q-network: observation to one value per action, through one ReLU hidden layer."""
    return nn.Sequential(nn.Linear(obs_len, hidden), nn.ReLU(), nn.Linear(hidden, actions))


def _init_weights(q: nn.Sequential, rng: np.random.Generator) -> None:
    """Uniform(+-1/sqrt(fan_in)) weights drawn from `rng`, zero biases (no global torch RNG)."""
    with torch.no_grad():
        for layer in q:
            if isinstance(layer, nn.Linear):
                bound = 1.0 / math.sqrt(layer.in_features)
                weights = rng.uniform(-bound, bound, size=tuple(layer.weight.shape))
                layer.weight.copy_(torch.as_tensor(weights, dtype=torch.float32))
                layer.bias.zero_()


def _greedy(q: nn.Sequential, obs: Array) -> Array:
    with torch.no_grad():
        values = q(torch.as_tensor(obs, dtype=torch.float32))
    return values.argmax(dim=1).numpy().astype(np.int64)


class GreedyPolicy:
    """A frozen copy of a Q-network acting greedily: the deterministic DQN policy."""

    def __init__(self, q: nn.Sequential) -> None:
        self._q = copy.deepcopy(q)

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        return _greedy(self._q, obs)


def greedy_policy(state: Mapping[str, object]) -> GreedyPolicy:
    """The greedy policy of a saved `DQN.state_dict()`; layer sizes come from the weights."""
    weights = {
        key.removeprefix("q."): torch.as_tensor(value, dtype=torch.float32)
        for key, value in state.items()
        if key.startswith("q.")
    }
    hidden, obs_len = weights["0.weight"].shape
    actions = weights["2.weight"].shape[0]
    q = q_network(obs_len, hidden, actions)
    q.load_state_dict(weights)
    return GreedyPolicy(q)


def _check_finite(value: torch.Tensor) -> None:
    number = float(value)
    if not math.isfinite(number):
        raise NonFiniteError(number)


class DQN:
    """Online one-step Q-learning on an MLP with epsilon-greedy exploration (spine)."""

    def __init__(
        self, config: MethodConfig, spec: WorldSpec, team: str, rng: np.random.Generator
    ) -> None:
        if not isinstance(spec.action, Discrete):
            raise ValueError(
                f"dqn needs a Discrete action space, not {type(spec.action).__name__}"
            )
        settings = full_settings(config.settings)
        self.team = team
        self._actions = spec.action.n
        self._gamma = float(settings["gamma"])
        self._epsilon_start = float(settings["epsilon_start"])
        self._epsilon_end = float(settings["epsilon_end"])
        self._decay_steps = int(settings["epsilon_decay_steps"])
        self._q = q_network(spec.obs_len, int(settings["hidden"]), self._actions)
        _init_weights(self._q, rng)
        self._optimizer = torch.optim.Adam(self._q.parameters(), lr=float(settings["lr"]))
        self._steps = 0

    def epsilon(self) -> float:
        """The exploration rate now: linear from start to end over the decay steps."""
        fraction = min(1.0, self._steps / self._decay_steps) if self._decay_steps > 0 else 1.0
        return self._epsilon_start + fraction * (self._epsilon_end - self._epsilon_start)

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        """Per agent row: a uniform random action with probability epsilon, else greedy."""
        actions = _greedy(self._q, obs)
        explore = rng.random(len(actions)) < self.epsilon()
        random_actions = rng.integers(self._actions, size=len(actions))
        return np.where(explore, random_actions, actions).astype(np.int64)

    def observe(self, t: Transition) -> None:
        """One gradient step on the one-step TD error of `t`'s active rows."""
        self._steps += 1
        active = torch.as_tensor(t.active, dtype=torch.bool)
        if not bool(active.any()):
            return
        obs = torch.as_tensor(t.obs, dtype=torch.float32)[active]
        next_obs = torch.as_tensor(t.next_obs, dtype=torch.float32)[active]
        actions = torch.as_tensor(t.actions, dtype=torch.int64)[active]
        rewards = torch.as_tensor(t.rewards, dtype=torch.float32)[active]
        with torch.no_grad():
            bootstrap = 0.0 if t.done else self._gamma
            targets = rewards + bootstrap * self._q(next_obs).max(dim=1).values
        chosen = self._q(obs).gather(1, actions.unsqueeze(1)).squeeze(1)
        loss = ((chosen - targets) ** 2).mean()
        _check_finite(loss)
        self._optimizer.zero_grad()
        loss.backward()
        _check_finite(sum(p.grad.sum() for p in self._q.parameters() if p.grad is not None))
        self._optimizer.step()

    def policy(self) -> Policy:
        """A frozen greedy copy; later training doesn't change it."""
        return GreedyPolicy(self._q)

    def state_dict(self) -> dict[str, object]:
        """The Q-network's weights under `q.` and the step count, for checkpoints."""
        state: dict[str, object] = {
            f"q.{key}": value.detach().clone() for key, value in self._q.state_dict().items()
        }
        state["steps"] = self._steps
        return state

